def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v not in (0, 3)]
    blank_cols = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 0 and all(grid[rr][cc] == 3 for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))):
                blank_cols.add(c)
    # Project four rays from every colored cross. Its own adjacent gray arms
    # are passed over; all other gray marks stop a ray. The blank cross column
    # remains empty on horizontal projections, but rays continue past it.
    for r, c, color in centers:
        for dc in (-1, 1):
            x = c + dc
            if 0 <= x < w and grid[r][x] == 3:
                x += dc
            while 0 <= x < w and grid[r][x] != 3:
                if grid[r][x] == 0 and x not in blank_cols:
                    out[r][x] = color
                x += dc
    # Vertical rays follow the same rule, and are applied after horizontal rays.
    for r, c, color in centers:
        for dr in (-1, 1):
            y = r + dr
            if 0 <= y < h and grid[y][c] == 3:
                y += dr
            while 0 <= y < h and grid[y][c] != 3:
                if grid[y][c] == 0:
                    out[y][c] = color
                y += dr
    return out
